import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const imageUrl = config.assets?.imageUrl || config.imageUrl;
  const position = config.position || [0, 0, 0];
  const rotation = config.rotation || [0, 0, 0];
  const scale = config.scale || [1, 1, 1];
  const colors = config.colors || {};
  const textContent = config.textContent || 'Collection 1';
  const cinematicPrimitives = config.cinematicPrimitives || [];

  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  const spriteHeight = 1.0;
  const spriteWidth = spriteHeight * 1.6;
  const geometry = new THREE.PlaneGeometry(spriteWidth, spriteHeight);

  const material = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  if (ctx.fontAtlas) {
    const textString = typeof textContent === 'string'
      ? textContent
      : textContent.text || 'Collection 1';

    try {
      const textMesh = ctx.fontAtlas({
        text: textString,
        fontSize: 0.34,
        weight: 400,
        font: 'Lora',
        color: colors.ink,
      });

      if (textMesh) {
        textMesh.position.z = 0.05;
        group.add(textMesh);
      }
    } catch (error) {
      console.warn('Text rendering failed:', error);
    }
  }

  group.position.set(...position);
  group.rotation.set(...rotation);
  group.scale.set(...scale);

  for (const primitive of cinematicPrimitives) {
    if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
      try {
        ctx.primitives[primitive.name](group, primitive.params || {});
      } catch (error) {
        console.warn(`Failed to apply primitive ${primitive.name}:`, error);
      }
    }
  }

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    gsap.killTweensOf(group);
  };

  group.userData.handlers = {};

  return group;
}
